import os
import sys
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))
import pytest

import pytest
from app.utils import DependencyResolver, CircularDependencyError, calculate_power, calculate_compound_interest, calculate_water_hardness, calculate_income_tax

def test_dependency_resolver_success():
    resolver = DependencyResolver()
    resolver.add_dependency('B', 'A')
    resolver.add_dependency('C', 'B')
    assert resolver.resolve_execution_order() == [['A'], ['B'], ['C']]

def test_dependency_resolver_circular():
    resolver = DependencyResolver()
    resolver.add_dependency('A', 'B')
    resolver.add_dependency('B', 'A')
    with pytest.raises(CircularDependencyError):
        resolver.resolve_execution_order()

def test_dependency_resolver_invalid_input():
    resolver = DependencyResolver()
    with pytest.raises(ValueError):
        resolver.add_dependency('', 'A')
    with pytest.raises(ValueError):
        resolver.add_dependency('A', 'A')

def test_calculate_power():
    assert calculate_power(2, 3) == 8.0
    assert calculate_power(5, 0) == 1.0

def test_calculate_compound_interest():
    assert calculate_compound_interest(100, 0.05, 1, 1) == 105.0
    with pytest.raises(ValueError):
        calculate_compound_interest(-100, 0.05, 1, 1)
    with pytest.raises(ValueError):
        calculate_compound_interest(100, 0.05, 1, 0)

def test_calculate_water_hardness():
    assert calculate_water_hardness(10, 10) == 66.15
    with pytest.raises(ValueError):
        calculate_water_hardness(-1, 10)

def test_calculate_income_tax():
    assert calculate_income_tax(1000, 0.1) == 100.0
    assert calculate_income_tax(1000, 0) == 0.0
    assert calculate_income_tax(1000, 1) == 1000.0
    with pytest.raises(ValueError):
        calculate_income_tax(-100, 0.1)
    with pytest.raises(ValueError):
        calculate_income_tax(1000, 1.1)
